import { MatMath } from "./Math/Matrix";
import { Primitives } from "./Mesh";
import { Renderer } from "./Renderer";
// renderer for a skybox
export class SkyboxRenderer extends Renderer {
    constructor(skybox, shader) {
        // super with "true" will put it at the top of the render list
        super(true);
        this.skybox = skybox;
        this.shader = shader;
    }
    draw(camera) {
        // load the square primitive
        const sqr = Primitives.Square;
        sqr.bindBuffers();
        this.shader.bindMeshAttribs();
        // load the material and texture
        this.skybox.attachToSlot(0);
        this.shader.setUniform1i("u_CubeMap", 0);
        this.shader.setUniformMat3f("u_RotationMat", MatMath.Resize(camera.InverseViewMatrix, 3, 3));
        this.shader.setUniformMat4f("u_InvProjection", MatMath.Inverse4(camera.ProjectionMatrix));
        // draw without modifying the depth buffer
        gl.disable(gl.DEPTH_TEST);
        gl.depthMask(false);
        gl.drawElements(gl.TRIANGLES, sqr.submeshes[0].length, gl.UNSIGNED_SHORT, sqr.submeshes[0].start);
        gl.enable(gl.DEPTH_TEST);
        gl.depthMask(true);
    }
}
