import { Renderer } from "./Renderer";
import { Mesh } from "./Mesh";
import { MatMath } from "./Math/Matrix";
import { VecMath } from "./Math/Vector";
// a class that draws the shadow of an object for a point light
export class ShadowRenderer extends Renderer {
    constructor(target, light, material) {
        super();
        this.material = material;
        this.target = target;
        this.light = light;
        // mesh is set to dynamic draw because it is updated every frame
        this.mesh = new Mesh([], [], [], gl.DYNAMIC_DRAW);
    }
    draw(camera) {
        if (!this.target.enabled)
            return;
        // update the shape of the shadow
        this.updateShadow();
        // load the mesh and material
        this.mesh.bindBuffers();
        this.material.activate();
        this.material.shader.setUniformMat4f("u_MVPMat", MatMath.MultiplyM(camera.ViewProjectionMatrix, this.transform.Matrix));
        // draw the shadow
        this.mesh.submeshes.forEach(submesh => {
            gl.drawElements(gl.TRIANGLES, submesh.length, gl.UNSIGNED_SHORT, submesh.start);
        });
    }
    updateShadow() {
        // copy the triangles and submeshes
        this.mesh.triangles = this.target.mesh.triangles;
        this.mesh.submeshes = this.target.mesh.submeshes;
        // create the transformation matrix to project the shadow onto the XZ plane
        let height = this.light.transform.WorldPosition[1];
        let transformation = MatMath.Identity(4);
        transformation = MatMath.MultiplyM(this.target.transform.Matrix, transformation);
        transformation = MatMath.MultiplyM(MatMath.Translate(VecMath.Negate(this.light.transform.WorldPosition)), transformation);
        transformation = MatMath.MultiplyM(MatMath.Shadow(height), transformation);
        transformation = MatMath.MultiplyM(MatMath.Translate(this.light.transform.WorldPosition), transformation);
        // transform each of the vertices
        this.mesh.vertices = [];
        this.target.mesh.vertices.forEach((vert) => {
            let newPoint = MatMath.MultiplyV(transformation, [...vert.point, 1]);
            this.mesh.vertices.push({
                color: [1, 1, 1],
                normal: [0, 1, 0],
                uv: [0, 0],
                point: VecMath.Divide(VecMath.Resize(newPoint, 3), newPoint[3])
            });
        });
        // reload the mesh buffers to fill their updated data
        this.mesh.refreshBuffer();
    }
}
