import { MatMath } from './Math/Matrix';
import { VecMath } from './Math/Vector';
// represents the transformations on an object
export class Transform {
    constructor() {
        this.pivot = VecMath.MakeEmpty(3); // Pivot allows the origin of the object to be changed
        this.position = VecMath.MakeEmpty(3);
        this.rotation = VecMath.MakeEmpty(3);
        this.scale = VecMath.MakeEmpty(3, 1);
        this.parent = null;
    }
    get WorldPosition() {
        return VecMath.Resize(MatMath.MultiplyV(this.Matrix, [0, 0, 0, 1]), 3);
    }
    get Forward() {
        return MatMath.MultiplyV(this.NormalMatrix, [0, 0, -1]);
    }
    get Right() {
        return MatMath.MultiplyV(this.NormalMatrix, [1, 0, 0]);
    }
    get Up() {
        return MatMath.MultiplyV(this.NormalMatrix, [0, 1, 0]);
    }
    // Get the local to world space transformation of
    // the transform including parent transforms
    get Matrix() {
        if (this.parent)
            return MatMath.MultiplyM(this.parent.Matrix, this.LocalMatrix);
        return this.LocalMatrix;
    }
    // Get the world to local space transformation of
    // the transform including parent transforms
    get InverseMatrix() {
        if (this.parent)
            return MatMath.MultiplyM(this.InverseLocalMatrix, this.parent.InverseMatrix);
        return this.InverseLocalMatrix;
    }
    // Get the local to world space transformation of
    // the transform excluding parent transforms
    get LocalMatrix() {
        return MatMath.Product(4, this.LocalTranslationMatrix, this.LocalRotationMatrix, this.LocalScaleMatrix, this.PivotMatrix);
    }
    // Get the world to local space transformation of
    // the transform excluding parent transforms
    get InverseLocalMatrix() {
        return MatMath.Product(4, this.InversePivotMatrix, this.InverseLocalScaleMatrix, this.InverseLocalRotationMatrix, this.InverseLocalTranslationMatrix);
    }
    // Get the matrix that represents the repositioning of the transform's pivot
    get PivotMatrix() {
        return MatMath.Translate(VecMath.Negate(this.pivot));
    }
    // Inverse of PivotMatrix
    get InversePivotMatrix() {
        return MatMath.Translate(this.pivot);
    }
    // Get the matrix that represents the scale of the transform
    get LocalScaleMatrix() {
        return MatMath.Scale(this.scale);
    }
    // Inverse of LocalScaleMatrix
    get InverseLocalScaleMatrix() {
        return MatMath.Scale([1 / this.scale[0], 1 / this.scale[1], 1 / this.scale[2]]);
    }
    // Get the matrix that represents the rotation of the transform
    get LocalRotationMatrix() {
        return MatMath.Product(4, MatMath.RotateZ(this.rotation[2]), MatMath.RotateY(this.rotation[1]), MatMath.RotateX(this.rotation[0]));
    }
    // Inverse of LocalRotationMatrix
    get InverseLocalRotationMatrix() {
        return MatMath.Product(4, MatMath.RotateX(-this.rotation[0]), MatMath.RotateY(-this.rotation[1]), MatMath.RotateZ(-this.rotation[2]));
    }
    // Get the matrix that represents the translation of the transform
    get LocalTranslationMatrix() {
        return MatMath.Translate(this.position);
    }
    // Inverse of LocalTranslationMatrix
    get InverseLocalTranslationMatrix() {
        return MatMath.Translate(VecMath.Negate(this.position));
    }
    // Get the matrix to translate the vertex normals from local to world space
    get NormalMatrix() {
        return MatMath.Resize(MatMath.Transpose(this.InverseMatrix), 3, 3);
    }
}
